// Independent of React navigation state: recover access after returning home.
(()=>{const link=document.createElement('a');link.href='/recording-monitor.html';link.textContent='后台正在录制 · 点击恢复录制画面与控制';Object.assign(link.style,{display:'none',position:'fixed',bottom:'22px',left:'24px',zIndex:'9999',padding:'16px 24px',background:'#b91c1c',color:'white',borderRadius:'10px',font:'16px system-ui',boxShadow:'0 3px 20px #0008'});document.body.append(link);async function poll(){try{const r=await fetch('/recording-status',{cache:'no-store'});if(r.ok){const s=await r.json();link.style.display=s.recording_active&&location.pathname!=='/recording'?'block':'none'}}catch{link.style.display='none'}finally{setTimeout(poll,3000)}}poll()})();
